-- LilKangooMedia Phase 15 | Service copy and features
-- Intentionally does not change any prices, pricing models, package IDs, extras,
-- images, booking status or payment settings. Review copy in docs/SERVICE-COPY-EN.md.
-- Keep this file private while reviewing; run in the LilKangooMedia Supabase SQL Editor.
BEGIN;

ALTER TABLE public.services
  ADD COLUMN IF NOT EXISTS features jsonb NOT NULL DEFAULT '[]'::jsonb;

-- Core service text and service-wide highlights.
WITH descriptions (slug, summary, description, highlights) AS (
  VALUES
    ('portrait-photography', 'We create natural portraits, couple sessions and family photographs in locations across Cyprus.', 'We plan every photography session around you, the people joining you and the kind of images you want to take home. We can photograph individuals, couples and families outdoors or at another agreed location, choosing the setting and pace to suit the occasion. Our packages vary by session length, number of locations and expected image quantity, so you can choose how much coverage you need. We''ll confirm the meeting point, schedule and final details before your session.', '["Portrait sessions for individuals, couples and families","Photography at agreed locations across Cyprus","Choice of shorter and longer sessions","Multiple locations with selected packages","Session planning around your occasion"]'::jsonb),
    ('personal-videography', 'We film personal moments and experiences and turn them into an edited video you can revisit.', 'We capture the people, atmosphere and moments that matter to you through personal videography. Before filming, we''ll discuss the occasion, location and the style of video you would like us to create. We then film and edit the material according to your chosen package. You can choose a shorter session for a concise film or longer coverage for more of the experience; the filming time and finished video length are specified in each option.', '["On-location filming for personal occasions","Planning based on your event or experience","Filming and video editing","Different filming durations","Finished video lengths specified by package"]'::jsonb),
    ('wedding-photography-video', 'We photograph and film weddings, engagements and proposals across Cyprus.', 'We document your celebration as it unfolds, combining personal portraits with the moments shared by you, your family and your guests. We plan the coverage around your ceremony, locations and schedule so you know what to expect on the day. You can choose photography coverage or a package that also includes video. The hours, number of edited photographs and any additional photoshoot time depend on the package you select.', '["Wedding, engagement and proposal coverage","Natural portraits and celebration photography","Photography and video options","Coverage planned around your timeline","Choice of shorter or full-day packages"]'::jsonb),
    ('cyprus-photo-trips', 'We combine private sightseeing across Cyprus with a personal photography experience.', 'We plan a private experience around the places you want to discover in Cyprus and photograph you along the way. The route and stops can be tailored to your interests and the time available. We offer experiences from five hours to two days, with the duration and included photograph quantity clearly listed in each package. Standard package descriptions are based on groups of up to four people; we confirm any additional participant costs in advance.', '["Private sightseeing and photography in one experience","Routes adapted to your interests and available time","Professional photographs taken during your trip","Half-day, full-day and longer options","Group size and photo allowance specified per package"]'::jsonb),
    ('cyprus-video-trips', 'We turn your private Cyprus experience into a personal travel film.', 'We combine a private trip around Cyprus with video production, filming the places you visit and the moments you want to remember. We discuss the route, activities and the kind of travel film you have in mind before setting out. Each option includes a defined trip duration and a maximum finished video length, from short highlights to a longer edit over two days. Standard packages are described for up to four people.', '["Private Cyprus experiences with filming","Routes and filming planned around your interests","Video editing after the trip","Several trip durations and film lengths","Package-specific group limits and deliverables"]'::jsonb),
    ('private-events', 'We photograph and film birthdays, anniversaries, christenings and private celebrations.', 'We help you keep a visual record of the celebrations that bring people together. Whether you need photographs of guests and the occasion, video highlights or both, we''ll plan coverage around your event schedule and location. Tell us what you''re celebrating, where the event will take place and how long you need us there. We''ll prepare a proposal describing the agreed coverage and deliverables before you confirm.', '["Birthday and anniversary coverage","Christenings and family celebrations","Photography or videography options","Coverage planned around your event","Individual proposal for each celebration"]'::jsonb),
    ('product-brand-photography', 'We photograph products, jewellery, people and spaces for brands and businesses.', 'We create commercial images that help you present what your business offers. Our photography covers products, jewellery, fine details, business portraits and promotional visuals. We start with your brief and discuss where the images will be used, the visual approach and what needs to be photographed. The number of final photographs, editing requirements and any usage arrangements are agreed as part of your individual quotation.', '["Product and jewellery photography","Detail and product presentation images","Business and brand portraits","Photographs for websites and campaigns","Project-specific shooting and editing plans"]'::jsonb),
    ('commercial-video-reels', 'We produce promotional films, social media reels and commercial video for businesses.', 'We help businesses tell their story through moving images, from short reels to longer promotional and event films. Together, we''ll plan the message, filming locations, style and formats needed for your chosen channels. We then film and edit the content according to the agreed brief. Production time, video length, number of edits and final deliverables are defined in the quotation for your project.', '["Social media reels and short-form videos","Brand and promotional films","Business and event videography","Filming and editing","Deliverables planned for your chosen channels"]'::jsonb),
    ('social-media-management', 'We help businesses plan, create and manage content for their social media channels.', 'We support businesses that want a more consistent and purposeful social media presence. Depending on the plan we agree, we can take care of content planning, photography, video, design, post preparation and account management. We discuss your goals, platforms and publishing frequency before defining the monthly scope. Reporting, content quantities and any on-location visits are included only where specified in your individual plan.', '["Content planning and social media strategy","Photography and video production options","Post and campaign design","Publishing and account management options","Scope and reporting agreed per plan"]'::jsonb),
    ('graphic-design', 'We design brand identities, illustrations and promotional graphics for businesses.', 'We create visual materials that help your brand communicate clearly and consistently. Our design work ranges from identity elements and illustrations to campaign graphics, posters and social media content. We start with your brief, discuss the style and where each design will be used, then agree the number and type of final files required. Each project is quoted according to its scope and deliverables.', '["Brand identity and visual design","Logo and identity work where agreed","Posters and promotional graphics","Illustrations and campaign visuals","Designs for social media and digital use"]'::jsonb),
    ('website-design', 'We design and develop websites, online stores and digital platforms for businesses.', 'We build digital experiences around what your business needs to show and do online. That may be a clear company website, an online shop or a more advanced platform with custom functionality. We''ll discuss the pages, content, design and features required before planning development. Your proposal will specify what is included, the project scope and any separately priced ongoing support or maintenance.', '["Responsive business websites","Online store options","Custom website features and integrations","Design and development around your brief","Optional support and maintenance arrangements"]'::jsonb),
    ('brand-launch-packages', 'We bring together the branding, website and creative materials you need to launch your business.', 'We help new businesses establish a coherent visual presence with combined creative services. Depending on the package you choose, we can work on your logo, brand identity, website design, print materials, photography, social media content and promotional video. The three options build from essential brand assets to a broader collection of marketing materials. We confirm the exact design files, content quantities and delivery schedule before work begins. These are creative launch services, not company registration or legal services.', '["Creative brand and visual identity setup","Logo, website and print design options","Photography in selected packages","Social content and promotional video in selected packages","Clearly agreed creative deliverables"]'::jsonb),
    ('marketing-advertising', 'We plan creative marketing campaigns and produce promotional content for businesses.', 'We work with businesses to develop campaign ideas and the creative materials needed to support them. Depending on your goals, that can involve photography, video, graphic design and digital promotion. We begin with your offer, audience and preferred channels, then propose a practical scope of work. We agree the campaign deliverables and any ongoing activity before production starts; advertising budgets and third-party costs are confirmed separately where relevant.', '["Marketing and campaign planning","Photography and video options for advertising","Campaign graphics and promotional assets","Content for relevant digital channels","Individual campaign scope and quotation"]'::jsonb),
    ('cypruseye-partner-advertising', 'We help tourism businesses reach visitors through monthly CyprusEye and WakacjeCypr advertising plans.', 'We connect tour operators, accommodation providers and local businesses with people exploring Cyprus through CyprusEye and WakacjeCypr. Our partner plans combine recommendation visibility with access to the partner dashboard, order management tools and affiliate opportunities. You can choose how prominently your business is presented, from a standard listing to featured placement with limited competition or category exclusivity within the agreed area of our platform. We confirm your business category, location and placement terms before activating your plan. Individual Facebook promotion can be arranged separately; publishing quantities are not automatically included in these subscriptions.', '["Promotion through CyprusEye and WakacjeCypr recommendations","Access to the partner dashboard","Tools to manage your own orders","Affiliate earning opportunities","Featured positioning in higher tiers","Competition protection in selected monthly plans"]'::jsonb)
)
UPDATE public.services AS s
SET summary = d.summary,
    description = d.description,
    features = d.highlights,
    title = CASE WHEN s.slug = 'brand-launch-packages' THEN 'Brand Launch & Creative Setup' ELSE s.title END
FROM descriptions AS d
WHERE s.slug = d.slug;

-- Add package-level features ONLY to packages that still match the old verified
-- description and do not already have a feature list. If a package has been
-- customized in the admin, leave that package untouched for manual review.
WITH verified_package_features (slug, package_id, original_description, highlights) AS (
 VALUES
  ('portrait-photography', 'photo-basic-·-1h', '1 hour, 1 location, approximately 20–50 images', '["1-hour photography session","One location","Approximately 20–50 photographs"]'::jsonb),
  ('portrait-photography', 'photo-combo-·-3h', '3 hours, up to 3 locations, approximately 60–100 images', '["3-hour photography session","Up to 3 locations","Approximately 60–100 photographs"]'::jsonb),
  ('portrait-photography', 'photo-all-day-·-8h', '8 hours, up to 5 locations, approximately 80–300 images', '["8-hour photography session","Up to 5 locations","Approximately 80–300 photographs"]'::jsonb),
  ('personal-videography', 'video-basic-·-1h', '1 hour on location, video up to 3 min', '["1 hour of on-location filming","Edited video up to 3 minutes"]'::jsonb),
  ('personal-videography', 'video-combo-·-3h', '3 hours filming, video up to 30 min', '["3 hours of filming","Edited video up to 30 minutes"]'::jsonb),
  ('personal-videography', 'video-all-day-·-8h', '8 hours filming, long-form video and short highlights', '["8 hours of filming","Long-form edited video","Short video highlights"]'::jsonb),
  ('wedding-photography-video', 'wedding-basic', 'Up to 5h; 150–300 edited images', '["Up to 5 hours of coverage","150–300 edited photographs"]'::jsonb),
  ('wedding-photography-video', 'wedding-combo', 'Up to 5h plus 1h photoshoot; 250–400 images and video', '["Up to 5 hours of coverage","Additional 1-hour photoshoot","250–400 photographs","Video included"]'::jsonb),
  ('wedding-photography-video', 'wedding-all-day', 'Up to 8h plus 2h photoshoot; 350–700 images and edited video', '["Up to 8 hours of coverage","Additional 2-hour photoshoot","350–700 photographs","Edited video included"]'::jsonb),
  ('cyprus-photo-trips', 'photo-trip-·-half-day-5h', 'Up to 30 photos; up to 4 people; additional participant pricing applies', '["Private experience lasting up to 5 hours","Up to 30 photographs","Up to 4 participants; additional participant pricing may apply"]'::jsonb),
  ('cyprus-photo-trips', 'photo-trip-·-3-4-day-8h', 'Up to 50 photos; up to 4 people', '["Private experience lasting up to 8 hours","Up to 50 photographs","Up to 4 participants"]'::jsonb),
  ('cyprus-photo-trips', 'photo-trip-·-all-day-10h', 'Up to 60 photos; up to 4 people', '["Private experience lasting up to 10 hours","Up to 60 photographs","Up to 4 participants"]'::jsonb),
  ('cyprus-photo-trips', 'photo-trip-·-two-days-20h', 'Up to 120 photos; up to 4 people', '["Private two-day experience, up to 20 hours","Up to 120 photographs","Up to 4 participants"]'::jsonb),
  ('cyprus-video-trips', 'video-trip-·-half-day-5h', 'Video up to 2 min, up to 4 people', '["Private experience lasting up to 5 hours","Edited video up to 2 minutes","Up to 4 participants"]'::jsonb),
  ('cyprus-video-trips', 'video-trip-·-3-4-day-8h', 'Video up to 3 min, up to 4 people', '["Private experience lasting up to 8 hours","Edited video up to 3 minutes","Up to 4 participants"]'::jsonb),
  ('cyprus-video-trips', 'video-trip-·-all-day-10h', 'Video up to 3 min, up to 4 people', '["Private experience lasting up to 10 hours","Edited video up to 3 minutes","Up to 4 participants"]'::jsonb),
  ('cyprus-video-trips', 'video-trip-·-two-days-20h', 'Video up to 6 min, up to 4 people', '["Private two-day experience, up to 20 hours","Edited video up to 6 minutes","Up to 4 participants"]'::jsonb),
  ('brand-launch-packages', 'basic-business-setup', 'Brand identity, logo, simple web design and print design', '["Brand identity and logo design","Simple website design","Print design"]'::jsonb),
  ('brand-launch-packages', 'simple-business-setup', 'Basic package with social media content and photography', '["Everything in Basic Business Setup","Social media content","Photography"]'::jsonb),
  ('brand-launch-packages', 'premium-business-setup', 'Extended setup including design, infographics, video ads and social media content', '["Extended branding and design","Infographics and visual materials","Video advertising","Social media content"]'::jsonb),
  ('cypruseye-partner-advertising', 'cypruseye-entry-50', 'Starter tier. Promotion in recommendations on CyprusEye.com and WakacjeCypr.com, access to the partner panel, management of your own orders, affiliate access and potential long-term affiliate earnings. Optional individual promotion through the Facebook groups and social profiles.', '["Recommendation visibility across CyprusEye and WakacjeCypr","Partner dashboard access","Management of your own orders","Affiliate system access"]'::jsonb),
  ('cypruseye-partner-advertising', 'cypruseye-featured-100', 'Featured tier. Everything in the €50 plan, plus featured placement in recommended areas on CyprusEye.com and WakacjeCypr.com. Individual promotion through the Facebook groups and social profiles is available as an option.', '["Everything in the entry plan","Featured recommendation placement"]'::jsonb),
  ('cypruseye-partner-advertising', 'cypruseye-limited-250', 'Limited-competition tier. Everything in the €100 plan, with featured placement and minimal competing partner exposure in the same service category and location. As an example, CyprusEye describes no more than one other accommodation partner in the same category and area. Optional individual Facebook promotion.', '["Everything in the featured plan","Featured visibility","Limited competing partner exposure in the same category and location"]'::jsonb),
  ('cypruseye-partner-advertising', 'cypruseye-exclusive-450', 'Exclusive tier. Everything in the €250 plan, with featured placement and no competing partner shown in the same category and nearby area on CyprusEye. Exclusivity applies to this platform placement, not to competitors elsewhere. Optional individual Facebook promotion.', '["Everything in the limited-competition plan","Featured visibility","No competing partner displayed in the same category and agreed area on CyprusEye"]'::jsonb)
)
UPDATE public.services AS s
SET packages = (
  SELECT COALESCE(jsonb_agg(
    CASE
      WHEN v.package_id IS NOT NULL
       AND item->>'description' = v.original_description
       AND (NOT (item ? 'features') OR item->'features' = '[]'::jsonb)
      THEN jsonb_set(item, '{features}', v.highlights, true)
      ELSE item
    END ORDER BY ordinality
  ), '[]'::jsonb)
  FROM jsonb_array_elements(s.packages) WITH ORDINALITY AS p(item, ordinality)
  LEFT JOIN verified_package_features AS v ON v.slug = s.slug AND v.package_id = item->>'id'
)
WHERE s.slug IN (SELECT DISTINCT slug FROM verified_package_features)
  AND jsonb_typeof(s.packages) = 'array';

COMMIT;

-- Verification: inspect service features, packages, and unchanged prices.
SELECT slug, title, jsonb_array_length(features) AS service_features,
       jsonb_array_length(packages) AS package_count,
       (SELECT COUNT(*) FROM jsonb_array_elements(packages) p
         WHERE p ? 'features' AND jsonb_typeof(p->'features')='array'
           AND jsonb_array_length(p->'features')>0) AS packages_with_features
FROM public.services
WHERE slug IN ('portrait-photography','personal-videography','wedding-photography-video','cyprus-photo-trips','cyprus-video-trips','private-events','product-brand-photography','commercial-video-reels','social-media-management','graphic-design','website-design','brand-launch-packages','marketing-advertising','cypruseye-partner-advertising')
ORDER BY sort_order;
